import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount1, uint256 amount2) public {
        // Bound amounts to prevent overflow while keeping wide domain
        amount1 = bound(amount1, 1, type(uint256).max / 2 - 1);
        amount2 = bound(amount2, 1, type(uint256).max / 2 - 1);

        // Use two different EOAs for the two deposits
        address alice = address(0x1000);
        address bob = address(0x2000);

        // Fund alice and bob
        vm.deal(alice, amount1);
        vm.deal(bob, amount2);

        // Alice makes first deposit
        vm.prank(alice);
        c.addToBalance{value: amount1}();

        // Bob makes second deposit
        vm.prank(bob);
        c.addToBalance{value: amount2}();

        // After both deposits, the sum of all balances should equal total ether received
        uint256 totalBalance = c.getBalance(alice) + c.getBalance(bob);
        uint256 totalReceived = amount1 + amount2;
        assertTrue(totalBalance == totalReceived);
    }
}

