        vm.assume(actor1 != address(0) && actor2 != address(0));
        vm.assume(actor1 != actor2);

        // Fund the test contract and actors
        vm.deal(address(this), value1 + value2);
        vm.deal(actor1, value1);
        vm.deal(actor2, value2);

        uint256 initialContractBalance = address(c).balance;

        // Actor1 adds to balance
        vm.prank(actor1);
        c.addToBalance{value: value1}();

        // Actor2 adds to balance
        vm.prank(actor2);
        c.addToBalance{value: value2}();

        uint256 sumBalances = c.getBalance(actor1) + c.getBalance(actor2);
        uint256 finalContractBalance = address(c).balance;

        assertTrue(sumBalances == finalContractBalance - initialContractBalance);
    }
